  return new Promise<void>((resolve) => {
    agent.process.on("exit", () => resolve());
    agent.client.close();
    // Give the client a moment to close, then force-kill
    setTimeout(() => {
      if (!agent.process.killed) agent.kill();
    }, 50);
  });
}

